var isAnagram = function(s, t) {
    if (s.length !== t.length) {
        return false;
    }

    // Count frequency of each character in s
    const count = {};
    for (const ch of s) {
        const current = count[ch] || 0;
        count[ch] = current + 1;
    }

    // Subtract frequency for each character in t
    for (const ch of t) {
        if (!count[ch]) {
            return false;
        }
        count[ch] = count[ch] - 1;
    }

    return true;
};

